def installed(name):
    if not isinstance(name,str) or not re.fullmatch(r'[a-z0-9][a-z0-9+.-]*(?::[a-z0-9][a-z0-9-]*)?',name):raise ValueError('literal package name required')
    result=subprocess.run(['dpkg-query','-W','-f=${binary:Package}\t${Version}\t${Architecture}\n','--',name],capture_output=True,text=True,timeout=4)
    if result.returncode==1:return None
    if result.returncode:raise RuntimeError(result.stderr)
    package,version,architecture=result.stdout.rstrip('\n').split('\t')
    return {'package':package,'version':version,'architecture':architecture}
