import gzip,tarfile,io,zlib
def inspect_archive(path):
    try:
        with open(path,'rb') as raw:
            if raw.read(2)!=b'\x1f\x8b':return {'gzip_ok':False,'tar_ok':False,'members':[]}
        with gzip.open(path,'rb') as stream:data=stream.read()
    except (OSError,EOFError,zlib.error):return {'gzip_ok':False,'tar_ok':False,'members':[]}
    try:
        with tarfile.open(fileobj=io.BytesIO(data),mode='r:') as archive:
            members=[member.name for member in archive.getmembers()]
    except tarfile.TarError:return {'gzip_ok':True,'tar_ok':False,'members':[]}
    return {'gzip_ok':True,'tar_ok':True,'members':members}
```

